ט. עִנְיַן מַעֲלַת הַהִתְבּוֹדְדוּת וְהַדִּבּוּר דִּקְדֻשָּׁה, וְשֶׁבּוֹ תָּלוּי כָּל נִצְחוֹן הַמִּלְחָמָה - עַיֵּן 'דִּבּוּר', אוֹתִיּוֹת ו ז. 
י. לִפְעָמִים גּוֹבֵר הַחַשְׁכוּת וְהֶעְדֵּר הַדַּעַת כָּל־כָּךְ עַל הָאָדָם, עַד שֶׁהוּא בִּבְחִינַת הֶעְדֵּר הַדִּבּוּר, בְּחִינַת יוֹנָה אִלֶּמֶת, שֶׁאֵינוֹ יָכוֹל לִפְתֹּחַ פִּיו כְּלָל לְהִתְפַּלֵּל וּלְהִתְבּוֹדֵד וּלְפָרֵשׁ שִׂיחָתוֹ כָּרָאוּי לוֹ, בִּבְחִינַת "נֶאֱלַמְתִּי לֹא אֶפְתַּח פִּי", וְנֶאֱמַר: "נֶאֱלַמְתִּי דוּמִיָּה וְכוּ'". וּבֶאֱמֶת לוּלֵא כֹּחַ הַצַּדִּיקִים הַגְּדוֹלִים, הָיוּ מִתְיָאֲשִׁים אָז לְגַמְרֵי מִלְּהִתְפַּלֵּל וְלָשׁוּב אֶל הַשֵּׁם. וְזֶה עִקַּר תִּקּוּן הַצַּדִּיקֵי־אֱמֶת, שֶׁהֵם בְּחִינַת יַעֲקֹב אָבִינוּ, שֶׁהֵם מְעוֹרְרִים וּמְחַזְּקִים אוֹתָנוּ גַּם אָז לְהִתְפַּלֵּל וְלָשׁוּב אֶל הַשֵּׁם וְלִבְלִי לְהִתְיָאֵשׁ מִן הַזְּעָקָה וּמִן הַתְּפִלָּה לְעוֹלָם, וּמַכְנִיסִין בְּלֵב יִשְׂרָאֵל, שֶׁגַּם בְּתֹקֶף מְרִירַת הַגָּלוּת בִּכְלָלִיּוּת וּבִפְרָטִיּוּת, בְּגַשְׁמִיּוּת וּבְרוּחָנִיּוּת, שֶׁהוּא בְּחִינַת תֹּקֶף חֶשְׁכַת לַיְלָה, אַף־עַל־פִּי־כֵן יִסְתַּכֵּל כָּל אֶחָד עַל נְקֻדַּת הָאֱמֶת לַאֲמִתּוֹ, עַד שֶׁכָּל אֶחָד יִתְחַזֵּק מִכָּל מָקוֹם שֶׁהוּא בִּרְצוֹנוֹת חֲזָקִים וְכִסּוּפִין טוֹבִים לְהַשֵּׁם יִתְבָּרַךְ, בִּבְחִינַת: "זָכַרְתִּי בַלַּיְלָה שִׁמְךָ ה'" וּבְחִינַת "עַל מִשְׁכָּבִי בַּלֵּילוֹת בִּקַּשְׁתִּי אֶת שֶׁאָהֲבָה נַפְשִׁי וְכוּ'", שֶׁגַּם בְּתֹקֶף חֶשְׁכַת הַלַּיְלָה נְבַקֵּשׁ וּנְחַפֵּשׂ אֶת הַשֵּׁם יִתְבָּרַךְ בִּרְצוֹנוֹת חֲזָקִים מְאֹד, כִּי סוֹף כָּל סוֹף מַה יִּהְיֶה הַתַּכְלִית מֵאִתָּנוּ; עַד שֶׁעַל־יְדֵי־זֶה מִמֵּילָא יִתְחַזֵּק לִפְתֹּחַ פִּיו בְּדִבּוּרֵי תְפִלָּה ק גַּם אָז, בִּבְחִינַת "נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר". וְאַחַר־כָּךְ, עַל־יְדֵי־זֶה בְּעַצְמוֹ שֶׁהוּא כּוֹסֵף וּמִשְׁתּוֹקֵק אַף־עַל־פִּי־כֵן מְאֹד לְהַשֵּׁם יִתְבָּרַךְ וּמִצְטַעֵר עַל זֶה, שֶׁהוּא בְּחִינַת הֶעְדֵּר הַדִּבּוּר, עַל־יְדֵי־זֶה: "חַם לִבִּי בְּקִרְבִּי וְכוּ' דִּבַּרְתִּי בִּלְשׁוֹנִי" - שֶׁזּוֹכֶה אַחַר־כָּךְ לְדַבֵּר דִּבּוּרִים קְדוֹשִׁים בַּחֲמִימוּת גָּדוֹל דִּקְדֻשָּׁה, מֵאַחַר שֶׁיָּצְאוּ הַדִּבּוּרִים עַל־יְדֵי רְצוֹנוֹת טוֹבִים וְכִסּוּפִין גְּדוֹלִים לְהַשֵּׁם יִתְבָּרַךְ. וּבֶאֱמֶת זֶה עִקַּר שְׁלֵמוּת הַתְּפִלָּה תָּמִיד, וְזֶה עִקַּר הָעֵצָה לְהַתְּפִלָּה וְשִׂיחָה וְהִתְבּוֹדְדוּת, שֶׁלֹּא יְהֵא הַדָּבָר עָלָיו כְּחוֹבָה, כְּמוֹ שֶׁצָּרִיךְ לָצֵאת יְדֵי חוֹבָתוֹ, שֶׁזֶּה בְּחִינַת: אַל תַּעַשׂ תְּפִלָּתְךָ קֶבַע, אֶלָּא רַחֲמִים וְתַחֲנוּנִים; שֶׁבַּתְּחִלָּה יְעוֹרֵר לִבּוֹ בִּרְצוֹנוֹת וְכִסּוּפִין טוֹבִים מְאֹד לְהַשֵּׁם יִתְבָּרַךְ, שֶׁאָז מִתְפַּלֵּל וּמְבַקֵּשׁ אַחַר־כָּךְ בֶּאֱמֶת מִקִּירוֹת לִבּוֹ בִּרְשׁוּתוֹ וּרְצוֹנוֹ הַטּוֹב, לֹא בְּדֶרֶךְ עֹל וְחִיּוּב לְבַד, רַק שֶׁאַף־עַל־פִּי־כֵן תִּקְּנוּ לָנוּ רַבּוֹתֵינוּ זַ"ל תְּפִלַּת חוֹבָה בִּשְׁבִיל הֲמוֹןשׂ עָם, כִּי בְּלֹא זֶה לֹא יִתְפַּלֵּל כְּלָל. אֲבָל עִקַּר שְׁלֵמוּת הַתְּפִלּוֹת אֵלּוּ בְּעַצְמָם - לְהִתְפַּלֵּל אוֹתָם בְּרַחֲמִים וְתַחֲנוּנִים, שֶׁלֹּא בְּדֶרֶךְ קֶבַע. וְעַל־ כֵּן תְּפִלּוֹת שֶׁל יוֹם, שַׁחֲרִית וּמִנְחָה, שֶׁהֵם בַּיּוֹם, הַיְנוּ בִּשְׁעַת הֶאָרַת הַמֹּחִין עֲדַיִן, עַל־כֵּן הֵם בְּחִינַת חוֹבָה; וְיַעֲקֹב תִּקֵּן תְּפִלַּת־עַרְבִית, הַיְנוּ לְהִתְפַּלֵּל גַּם בְּתֹקֶף חֶשְׁכַת לַיְלָה, בִּשְׁעַת הִסְתַּלְּקוּת הַמֹּחִין לְגַמְרֵי, וְאָז אִי אֶפְשָׁר לְתַקֵּן תְּפִלַּת חוֹבָה, דְּהַיְנוּ לְהַטִּיל עָלָיו חִיּוּב לְהִתְפַּלֵּל אָז, מֵחֲמַת שֶׁהוּא אָז בִּבְחִינַת הֶעְדֵּר הַדַּעַת וְהֶעְדֵּר הַדִּבּוּר וְאִי אֶפְשָׁר לוֹ לִפְתֹּחַ פִּיו כְּלָל, וְעַל־כֵּן אָז עִקַּר תִּקּוּן הַתְּפִלָּה עַל־יְדֵי בְּחִינַת תְּפִלַּת־עַרְבִית רְשׁוּת, לְהַמְשִׁיךְ עַל עַצְמוֹ גַּם אָז הֶאָרַת הָאֱמֶת מֵאוֹר הַפָּנִים שֶׁל הַצַּדִּיקֵי־אֱמֶת, שֶׁהֵם בְּחִינַת יַעֲקֹב, וְאוֹר הַפָּנִים הַנַּ"ל הוּא בְּחִינַת רָצוֹן, וְעַל־יְדֵי־זֶה יִזְכֶּה לְחַזֵּק אֶת עַצְמוֹ עַל־כָּל־פָּנִים בִּרְצוֹנוֹת וְכִסּוּפִין טוֹבִים, וְאָז מִמֵּילָא יִהְיֶה נִפְתָּח פִּיו בְּדִבּוּרִים קְדוֹשִׁים, וְיִשְׁפֹּךְ לִבּוֹ כַּמַּיִם לִפְנֵי ה' מֵחֲמַת תֹּקֶף הָרָצוֹן וְכִסּוּפָיו הַטּוֹבִים, שֶׁזֶּה עִקַּר שְׁלֵמוּת הַתְּפִלָּה תָּמִיד (הלכות תפלת המנחה, הל' ז,

